-- ==============================================================================
-- V19: Tích hợp đầy đủ 34 tỉnh thành và 3.321 xã phường trực thuộc (Mô hình 2 cấp)
-- Nạp dữ liệu chuẩn UTF-8 chuẩn xác, cập nhật rooms theo mã tỉnh/xã mới
-- ==============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Chuyển đổi mã tỉnh cho các phòng hiện tại sang mã hành chính chuẩn mới
UPDATE rooms SET province_code = '01' WHERE province_code = 'HN';
UPDATE rooms SET province_code = '79' WHERE province_code IN ('HCM', 'BDG');
UPDATE rooms SET province_code = '31' WHERE province_code = 'HP';
UPDATE rooms SET province_code = '48' WHERE province_code = 'DNG';
UPDATE rooms SET province_code = '92' WHERE province_code = 'CT';
UPDATE rooms SET province_code = '46' WHERE province_code = 'HUE';
UPDATE rooms SET province_code = '24' WHERE province_code = 'BN';

-- 2. Xóa và tái tạo dữ liệu bảng wards & provinces
TRUNCATE TABLE wards;
TRUNCATE TABLE provinces;

