-- 5. Cập nhật ward_id và ward_code của các phòng cũ sang xã/phường hợp lệ đầu tiên trong tỉnh
UPDATE rooms r
JOIN (
    SELECT province_code, MIN(id) AS first_ward_id, MIN(code) AS first_ward_code
    FROM wards
    GROUP BY province_code
) w ON r.province_code = w.province_code
SET r.ward_id = w.first_ward_id, r.ward_code = w.first_ward_code;

SET FOREIGN_KEY_CHECKS = 1;
